MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register ssize_t x;
    ssize_t y;
    Quantum *q;
    size_t number_pixels;
    MagickBooleanType status = MagickTrue;
    size_t width = image->columns;
    size_t height = image->rows;
    size_t depth = image->depth;
    PixelTrait traits = UndefinedPixelTrait;
    PixelInfo pixel_info;

    number_pixels = width * height;
    GetPixelInfoImage(image, &pixel_info);

    for (y = 0; y < (ssize_t) height; y++) {
        q = SetImagePixels(image, 0, y, width, 1);
        if (q == (Quantum *) NULL)
            break;
        if (SyncCacheLine(image, 0, y, width, 1, exception) != MagickFalse) {
            for (x = 0; x < (ssize_t) width; x++) {
                switch (inDocInfo->image_type) {
                    case GIMP_GRAY:
                        pixel_info.red = pixel_info.green = pixel_info.blue = q[0];
                        break;
                    case GIMP_RGB:
                        pixel_info.red = q[0];
                        pixel_info.green = q[1];
                        pixel_info.blue = q[2];
                        break;
                    default:
                        break;
                }
                if (inLayerInfo->has_alpha)
                    pixel_info.alpha = q[3];
                SetPixelInfo(tile_image, &pixel_info, x, y, traits);
                q += 4;
            }
        }
        if (!SyncImagePixels(tile_image, exception))
            status = MagickFalse;
    }

    return status;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register ssize_t x;
    Quantum *q;
    size_t number_pixels = image->columns * image->rows;
    QuantumType *pixel_data = (QuantumType *) AcquireQuantumMemory(number_pixels, sizeof(*pixel_data));
    if (pixel_data == (QuantumType *) NULL)
        return MagickFalse;

    // Read pixel data from the source image
    for (x = 0; x < (ssize_t) number_pixels; x++) {
        if ((inLayerInfo->alpha[x] & 0x80) != 0)
            pixel_data[x] = inDocInfo->type == GIMP_GRAY ? inLayerInfo->red[x] : inLayerInfo->blue[x];
        else
            pixel_data[x] = inDocInfo->type == GIMP_GRAY ? inLayerInfo->red[x] : inLayerInfo->green[x];
    }

    // Set pixel values in the destination tile image
    q = SetImagePixels(tile_image, 0, 0, tile_image->columns, tile_image->rows, exception);
    if (q == (Quantum *) NULL)
    {
        RelinquishMemory(pixel_data);
        return MagickFalse;
    }

    for (x = 0; x < (ssize_t) number_pixels; x++)
        *q++ = pixel_data[x];

    if (!SyncImagePixels(tile_image))
    {
        RelinquishMemory(pixel_data);
        return MagickFalse;
    }

    RelinquishMemory(pixel_data);
    return MagickTrue;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register ssize_t x;
    ssize_t y;
    MagickBooleanType status = MagickTrue;
    Quantum *q;
    size_t length;
    void *pixel_data;

    if (inDocInfo->image_type == GIMP_GRAY)
        length = (size_t) inLayerInfo->width;
    else
        length = 3 * (size_t) inLayerInfo->width;

    if ((pixel_data = AcquireMemory(length)) == (void *) NULL)
        return MagickFalse;

    for (y = 0; y < (ssize_t) inLayerInfo->height; y++) {
        register ssize_t i;
        register ssize_t x_offset = inLayerInfo->offset_x;

        q = (Quantum *) SetImagePixels(image, (ssize_t) x_offset, y + inLayerInfo->offset_y, inLayerInfo->width, 1);
        if (q == (Quantum *) NULL)
            break;
        if (ReadPixelData((unsigned char *) pixel_data, length) != MagickTrue) {
            status = MagickFalse;
            break;
        }

        i = 0;
        for (x = 0; x < (ssize_t) inLayerInfo->width; x++) {
            if (inDocInfo->image_type == GIMP_GRAY) {
                register unsigned char *alpha;
                alpha = inLayerInfo->alpha;
                if (alpha != (unsigned char *) NULL)
                    q[0] = pixel_data[i++];
                else {
                    q[0] = 255;
                    i++;
                }
                q += 1;
            }
            else {
                register unsigned char *alpha;
                alpha = inLayerInfo->alpha;
                if (alpha != (unsigned char *) NULL)
                    q[0] = pixel_data[i++];
                else {
                    q[0] = 255;
                    i++;
                }
                q[1] = pixel_data[i++];
                q[2] = pixel_data[i++];
                q += 3;
            }
        }
        if (SyncImagePixels(tile_image) == MagickFalse) {
            status = MagickFalse;
            break;
        }
    }

    if (data_length != (size_t) length)
        status = MagickFalse;

    if (pixel_data != (void *) NULL)
        pixel_data = RelinquishMemory(pixel_data);

    return status;
}

