MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register PixelIntensity *q;
    PixelIntensity *pixel_data;
    size_t width, height;

    width = image->columns;
    height = image->rows;

    pixel_data = (PixelIntensity *) AcquireMemory(data_length * sizeof(*pixel_data));
    if (!pixel_data)
        return MagickFalse;

    if (ReadPixelData(image, 0, 0, width, height, GrayAlphaPixel, pixel_data, exception) != MagickTrue) {
        RelinquishMemory(pixel_data);
        return MagickFalse;
    }

    if (inDocInfo->image_type == GIMP_GRAY || inDocInfo->image_type == GIMP_GRAY_ALPHA) {
        register ssize_t x;
        register ssize_t y;

        q = SetImagePixels(tile_image, 0, 0, width, height, exception);
        if (q == (PixelIntensity *) NULL)
            return MagickFalse;

        for (y = 0; y < (ssize_t) height; y++) {
            for (x = 0; x < (ssize_t) width; x++) {
                *q++ = *pixel_data++;
                *q++ = *pixel_data++;
            }

            if (!SyncImagePixels(tile_image))
                return MagickFalse;
            q = SetImagePixels(tile_image, 0, y + 1, width, 1, exception);
        }
    }
    else if (inDocInfo->image_type == GIMP_RGB || inDocInfo->image_type == GIMP_RGB_ALPHA) {
        register ssize_t x;
        register ssize_t y;

        q = SetImagePixels(tile_image, 0, 0, width, height, exception);
        if (q == (PixelIntensity *) NULL)
            return MagickFalse;

        for (y = 0; y < (ssize_t) height; y++) {
            for (x = 0; x < (ssize_t) width; x++) {
                *q++ = *pixel_data++;
                *q++ = *pixel_data++;
                *q++ = *pixel_data++;
                *q++ = *pixel_data++;
            }

            if (!SyncImagePixels(tile_image))
                return MagickFalse;
            q = SetImagePixels(tile_image, 0, y + 1, width, 1, exception);
        }
    }

    RelinquishMemory(pixel_data);
    return MagickTrue;
}
